So @paulidale, it sounds like you're planning on something like this:

``` C
EVP_MD_free(const EVP_MD *);
```

From an API design point of view, that is *weird*.
If we're doing this, I would say that it's wiser to do it like this:

``` diff
diff --git a/crypto/evp/digest.c b/crypto/evp/digest.c
index 3dfcfcda8e..1696d3fb11 100644
--- a/crypto/evp/digest.c
+++ b/crypto/evp/digest.c
@@ -1017,7 +1017,7 @@ void EVP_MD_free(EVP_MD *md)
 {
     int i;
 
-    if (md == NULL)
+    if (md == NULL || md->prov == NULL)
         return;
 
     CRYPTO_DOWN_REF(&md->refcnt, &i, md->lock);
diff --git a/crypto/evp/names.c b/crypto/evp/names.c
index cb59813857..1c8c84f741 100644
--- a/crypto/evp/names.c
+++ b/crypto/evp/names.c
@@ -105,29 +105,29 @@ const EVP_CIPHER *evp_get_cipherbyname_ex(OSSL_LIB_CTX *libctx,
 
 static void digest_from_name(const char *name, void *data)
 {
-    const EVP_MD **md = data;
+    EVP_MD **md = data;
 
     if (*md != NULL)
         return;
 
-    *md = (const EVP_MD *)OBJ_NAME_get(name, OBJ_NAME_TYPE_MD_METH);
+    *md = (EVP_MD *)OBJ_NAME_get(name, OBJ_NAME_TYPE_MD_METH);
 }
 
-const EVP_MD *EVP_get_digestbyname(const char *name)
+EVP_MD *EVP_get_digestbyname(const char *name)
 {
     return evp_get_digestbyname_ex(NULL, name);
 }
 
-const EVP_MD *evp_get_digestbyname_ex(OSSL_LIB_CTX *libctx, const char *name)
+EVP_MD *evp_get_digestbyname_ex(OSSL_LIB_CTX *libctx, const char *name)
 {
-    const EVP_MD *dp;
+    EVP_MD *dp;
     OSSL_NAMEMAP *namemap;
     int id;
 
     if (!OPENSSL_init_crypto(OPENSSL_INIT_ADD_ALL_DIGESTS, NULL))
         return NULL;
 
-    dp = (const EVP_MD *)OBJ_NAME_get(name, OBJ_NAME_TYPE_MD_METH);
+    dp = (EVP_MD *)OBJ_NAME_get(name, OBJ_NAME_TYPE_MD_METH);
 
     if (dp != NULL)
         return dp;
diff --git a/include/openssl/evp.h b/include/openssl/evp.h
index 5f9de9d8b9..7658a90c1a 100644
--- a/include/openssl/evp.h
+++ b/include/openssl/evp.h
@@ -1100,7 +1100,7 @@ int EVP_add_cipher(const EVP_CIPHER *cipher);
 int EVP_add_digest(const EVP_MD *digest);
 
 const EVP_CIPHER *EVP_get_cipherbyname(const char *name);
-const EVP_MD *EVP_get_digestbyname(const char *name);
+EVP_MD *EVP_get_digestbyname(const char *name);
 
 void EVP_CIPHER_do_all(void (*fn) (const EVP_CIPHER *ciph,
                                    const char *from, const char *to, void *x),
```
